<script lang="ts">
 import {tick,onMount,onDestroy} from 'svelte';import {page} from '$app/state';import {invalidateAll} from '$app/navigation';import Icon from './Icon.svelte';import 'leaflet/dist/leaflet.css';
 let {model,t,canEdit}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string;canEdit:boolean}=$props();let container=$state<HTMLDivElement>(),map:import('leaflet').Map|undefined,lib:typeof import('leaflet')|undefined,previewLayer:import('leaflet').Polygon|undefined,parcels:import('leaflet').FeatureGroup|undefined,tiles:import('leaflet').TileLayer|undefined;
 let opened=$state(false),vineyard=$state(''),coordinates=$state<[number,number][]>([]),drawing=$state(false),busy=$state(false),message=$state(''),street=$state(false),loading=$state(false),lastQuery=$state(''),mounted=$state(false),destroyed=false;
 onMount(()=>{mounted=true;open();});
 async function open(){try{await tick();lib=await import('leaflet');if(destroyed||!container)return;map=lib.map(container,{scrollWheelZoom:false,zoomControl:false}).setView([50.08,7.12],12);lib.control.zoom({zoomInTitle:t('uxZoomIn'),zoomOutTitle:t('uxZoomOut')}).addTo(map);container.setAttribute('role','region');container.setAttribute('aria-label',t('parcelMap'));parcels=lib.featureGroup().addTo(map);refresh();map.on('click',e=>{if(!drawing)return;coordinates=[...coordinates,[e.latlng.lng,e.latlng.lat]];draw();});opened=true;}catch{message=t('CONNECTION_FAILED');}}
 function refresh(){if(!lib||!map||!parcels)return;parcels.clearLayers();for(const v of model.vineyards){if(!v.geometry)continue;const label=document.createElement('span');label.textContent=v.code+' · '+v.name;const selected=v.id===vineyard;const layer=lib.geoJSON(v.geometry,{style:{color:selected?'#125941':'#2c8d68',weight:selected?3:2,fillColor:selected?'#1a8760':'#74bda1',fillOpacity:selected?.32:.15}}).bindTooltip(label).on('click',()=>{if(!drawing)vineyard=v.id;}).addTo(parcels);if(selected)map.fitBounds(layer.getBounds(),{padding:[70,70],maxZoom:17});}if(!vineyard){const bounds=parcels.getBounds();if(bounds.isValid())map.fitBounds(bounds,{padding:[35,35],maxZoom:16});}}
 $effect(()=>{if(!mounted)return;const query=page.url.searchParams.get('vineyard')??'';if(query!==lastQuery){lastQuery=query;if(model.vineyards.some(v=>v.id===query))vineyard=query;}void model.vineyards;void vineyard;if(opened&&!drawing)refresh();});
 function draw(){if(!map||!lib)return;previewLayer?.remove();previewLayer=lib.polygon(coordinates.map(([lon,lat])=>[lat,lon]),{color:'#c38823',weight:3,fillOpacity:.2}).addTo(map);}
 async function streetMap(){if(!map||!lib||loading)return;if(street){tiles?.remove();street=false;return;}loading=true;message='';try{
  // The public OSM service requires a valid Referer. Send only the app origin;
  // private routes and query parameters never leave the app. Test one visible tile
  // before attaching a layer, so blocked PNGs cannot cover the parcel view.
  const center=map.getCenter(),z=map.getZoom(),scale=2**z,x=Math.floor((center.lng+180)/360*scale),rad=center.lat*Math.PI/180,y=Math.floor((1-Math.asinh(Math.tan(rad))/Math.PI)/2*scale);
  const response=await fetch(`https://tile.openstreetmap.org/${z}/${x}/${y}.png`,{referrerPolicy:'strict-origin',credentials:'omit',signal:AbortSignal.timeout(12000)});
  if(!response.ok)throw Error('BASEMAP_UNAVAILABLE');await response.blob();if(destroyed)return;
  tiles=lib.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>',maxZoom:19,referrerPolicy:'strict-origin',crossOrigin:true}).addTo(map);
  tiles.on('tileerror',()=>{tiles?.remove();street=false;message=t('uxMapUnavailable');});street=true;
 }catch{tiles?.remove();street=false;message=t('uxMapUnavailable');}finally{loading=false;}}
 async function file(event:Event){const selected=(event.currentTarget as HTMLInputElement).files?.[0];if(!selected)return;if(selected.size>1000000){message=t('INVALID_GEOMETRY');return;}try{const json=JSON.parse(await selected.text());const geometry=json.type==='FeatureCollection'?json.features[0]?.geometry:json.type==='Feature'?json.geometry:json;if(geometry?.type!=='Polygon'||!Array.isArray(geometry.coordinates?.[0]))throw Error();const points=geometry.coordinates[0];if(points.length<4||points.some((p:any)=>!Array.isArray(p)||p.length!==2||!p.every(Number.isFinite)||Math.abs(p[0])>180||Math.abs(p[1])>90))throw Error();coordinates=points.slice(0,-1);drawing=true;draw();if(lib&&map&&previewLayer)map.fitBounds(previewLayer.getBounds(),{padding:[35,35]});message='';}catch{message=t('INVALID_GEOMETRY');}}
 async function save(){const parcel=model.vineyards.find(v=>v.id===vineyard);if(!parcel||coordinates.length<3)return;busy=true;try{const res=await fetch('/api/commands',{method:'POST',headers:{'content-type':'application/json','idempotency-key':crypto.randomUUID()},body:JSON.stringify({type:'vineyard_geometry',vineyard_id:vineyard,expected_version:parcel.version,geometry:{type:'Polygon',coordinates:[[...coordinates,coordinates[0]]]}})});message=res.ok?t('saved'):t((await res.json()).message);if(res.ok){drawing=false;coordinates=[];previewLayer?.remove();await invalidateAll();refresh();}}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
 onDestroy(()=>{destroyed=true;map?.remove();});
</script>
<section class="card"><div class="map-heading"><div><h2>{t('parcelMap')}</h2><p class="muted">{t('uxMapHint')}</p></div><button class="secondary" disabled={!opened||loading} aria-pressed={street} onclick={streetMap}>{loading?t('saving'):street?t('uxMapLocal'):t('uxMapStreet')}</button></div><div class="map schematic" class:street bind:this={container}></div><div class="map-controls"><label>{t('vineyard_id')}<select bind:value={vineyard}><option value="">{t('all')}</option>{#each model.vineyards as v}<option value={v.id}>{v.code} · {v.name}</option>{/each}</select></label><span class="pill good"><Icon name="vineyard" size={14}/>{model.vineyards.filter(v=>v.geometry).length} {t('vineyard')}</span></div>{#if canEdit}<details><summary>{t('drawPolygon')} / GeoJSON</summary><p class="muted">{t('uxMapDraw')}</p><div class="actions"><button class="secondary" disabled={!vineyard} onclick={()=>{drawing=!drawing;coordinates=[];previewLayer?.remove();}}>{drawing?t('stopDrawing'):t('drawPolygon')}</button><button class="secondary" disabled={!coordinates.length} onclick={()=>{coordinates=coordinates.slice(0,-1);draw();}}>{t('undoPoint')}</button><button onclick={save} disabled={busy||!vineyard||coordinates.length<3}>{t('saveGeometry')}</button><span class="pill">{coordinates.length}</span></div><label class="file">GeoJSON<input type="file" accept=".json,.geojson" onchange={file} /></label><p class="muted">{t('geometryHint')}</p></details>{/if}{#if message}<p class="notice" role="status">{message}</p>{/if}</section>
<style>.map-heading{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.map-heading h2{margin:0 0 8px}.map-heading p{margin-bottom:18px;max-width:670px;font-size:11px}.map-heading button{font-size:11px;white-space:nowrap}.map{height:370px;width:100%;z-index:0;border:1px solid #d9e6dd;border-radius:11px;margin-bottom:18px}.schematic{background-color:#f0f5ee;background-image:linear-gradient(#dce9db88 1px,transparent 1px),linear-gradient(90deg,#dce9db88 1px,transparent 1px);background-size:35px 35px}.street{background:#f0f5ee}.map-controls{display:flex;gap:18px;align-items:flex-end;justify-content:space-between}.map-controls label{flex:1;max-width:440px}details{margin-top:16px;border-top:1px solid var(--line);padding-top:6px}details summary{font-size:12px}details .file{margin-top:18px;max-width:440px}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions button{font-size:11px}@media(max-width:640px){.map{height:290px}.map-heading{flex-direction:column;gap:0}.map-heading button{margin-bottom:14px}.map-controls{align-items:flex-start;flex-direction:column}.map-controls label{width:100%}}</style>
